int lego_usb_tower_init(struct usb_interface *interface, const struct usb_device_id *id) {
    struct usb_device *udev = interface_to_usbdev(interface);
    struct lego_usb_tower_device *dev;
    int retval = -ENOMEM;

    dev = kzalloc(sizeof(*dev), GFP_KERNEL);
    if (!dev)
        return retval;

    usb_set_intfdata(interface, dev);

    spin_lock_init(&dev->lock);

    dev->udev = usb_get_dev(udev);
    dev->interface = interface;

    if (usb_find_common_endpoints(interface, &dev->int_in, NULL, NULL, NULL)) {
        dev_err(&interface->dev, "Could not find interrupt endpoints\n");
        goto error;
    }

    dev->irq_buffer = usb_buffer_alloc(udev, LEGO_USB_TOWER_BUFFER_SIZE, GFP_KERNEL, &dev->dma);
    if (!dev->irq_buffer)
        goto error;

    dev_info(&interface->dev, "USB LEGO Tower device initialized with firmware version %d.%d\n",
             LEGO_USB_TOWER_MAJOR_VERSION, LEGO_USB_TOWER_MINOR_VERSION);

    return 0;

error:
    usb_free_dev(dev->udev);
    kfree(dev);
    return retval;
}

int lego_usb_tower_init(struct usb_interface *interface, const struct usb_device_id *id) {
    struct usb_device *udev = interface_to_usbdev(interface);
    struct lego_usb_tower_dev *dev;
    int retval = -ENOMEM;

    dev = kzalloc(sizeof(*dev), GFP_KERNEL);
    if (!dev)
        goto error;

    spin_lock_init(&dev->lock);
    mutex_init(&dev->io_mutex);

    dev->interface = interface;
    dev->udev = usb_get_dev(udev);
    dev->id = id;

    usb_set_intfdata(interface, dev);

    if (usb_find_int_in_endpoint(udev->actconfig, &dev->int_in_endpoint)) {
        dev_err(&udev->dev, "Could not find interrupt in endpoint\n");
        goto error;
    }

    dev->interrupt = usb_alloc_urb(0, GFP_KERNEL);
    if (!dev->interrupt)
        goto error;

    dev->read_buffer = kmalloc(LEGOWRT_READ_BUFFER_SIZE, GFP_KERNEL);
    if (!dev->read_buffer)
        goto error;

    dev->write_buffer = kmalloc(LEGOWRT_WRITE_BUFFER_SIZE, GFP_KERNEL);
    if (!dev->write_buffer)
        goto error;

    retval = usb_get_string_descriptor(udev, 1, udev->descriptor.bcdDevice >> 8, dev->firmware_version, sizeof(dev->firmware_version));
    if (retval < 0) {
        dev_warn(&udev->dev, "Failed to read firmware version: %d\n", retval);
    }

    usb_register_dev(interface, &lego_usb_tower_class);

    return 0;

error:
    if (dev) {
        if (dev->interrupt)
            usb_free_urb(dev->interrupt);
        if (dev->read_buffer)
            kfree(dev->read_buffer);
        if (dev->write_buffer)
            kfree(dev->write_buffer);
        kfree(dev);
    }

    return retval;
}

int lego_usb_tower_init(struct usb_interface *interface, const struct usb_device_id *id) {
    int ret;
    struct usb_device *udev = interface_to_usbdev(interface);
    struct lego_usb_tower_dev *dev;
    int ifnum = interface->altsetting[0].desc.bInterfaceNumber;

    dev = kzalloc(sizeof(*dev), GFP_KERNEL);
    if (!dev)
        return -ENOMEM;

    dev->interface = interface;
    dev->udev = udev;
    usb_set_intfdata(interface, dev);

    spin_lock_init(&dev->lock);
    mutex_init(&dev->led_mutex);
    mutex_init(&dev->version_mutex);

    ret = usb_find_altsetting(udev->actconfig, ifnum);
    if (!ret) {
        ret = -ENODEV;
        goto error;
    }

    dev->int_in = usb_find_interval(udev, ifnum, 0);
    if (!dev->int_in) {
        ret = -ENODEV;
        goto error;
    }

    dev->readbuf = kmalloc(USB_BUFFER_SIZE, GFP_KERNEL);
    if (!dev->readbuf) {
        ret = -ENOMEM;
        goto error;
    }

    dev->writebuf = kmalloc(USB_BUFFER_SIZE, GFP_KERNEL);
    if (!dev->writebuf) {
        ret = -ENOMEM;
        goto error;
    }

    ret = usb_submit_urb(dev->int_in, GFP_KERNEL);
    if (ret < 0)
        goto error;

    ret = lego_usb_get_version(dev);
    if (ret < 0)
        goto error;

    usb_register_dev(interface, &lego_usb_tower_class);
    return 0;

error:
    if (dev->readbuf)
        kfree(dev->readbuf);
    if (dev->writebuf)
        kfree(dev->writebuf);
    if (dev)
        kfree(dev);
    return ret;
}

int lego_usb_tower_init(struct usb_interface *interface, const struct usb_device_id *id) {
    struct usb_device *udev = interface_to_usbdev(interface);
    struct lego_usb_tower_dev *dev;
    int retval = -ENOMEM;

    dev = kzalloc(sizeof(*dev), GFP_KERNEL);
    if (!dev)
        goto error;

    spin_lock_init(&dev->lock);

    if (usb_set_interface(udev, 0, 0))
        goto error;

    if (usb_find_int_in_endpoint(udev, &dev->int_in_endpoint))
        goto error;

    dev->int_in_urb = usb_alloc_urb(0, GFP_KERNEL);
    if (!dev->int_in_urb)
        goto error;

    dev->read_buffer = kmalloc(LEGOWRT_READ_BUFFER_SIZE, GFP_KERNEL);
    if (!dev->read_buffer)
        goto error;

    dev->write_buffer = kmalloc(LEGOWRT_WRITE_BUFFER_SIZE, GFP_KERNEL);
    if (!dev->write_buffer)
        goto error;

    dev->interface = interface;
    usb_set_intfdata(interface, dev);

    if (lego_usb_tower_get_fw_version(dev)) {
        dev_dbg(&udev->dev, "failed to get firmware version\n");
        goto error;
    }

    return 0;

error:
    kfree(dev->write_buffer);
    kfree(dev->read_buffer);
    usb_free_urb(dev->int_in_urb);
    kfree(dev);
    return retval;
}

int lego_usb_tower_init(struct usb_interface *interface, const struct usb_device_id *id) {
    struct usb_device *udev = interface_to_usbdev(interface);
    struct lego_usb_device *dev;
    int i, retval = -ENOMEM;

    dev = kzalloc(sizeof(*dev), GFP_KERNEL);
    if (!dev)
        return -ENOMEM;

    spin_lock_init(&dev->lock);
    mutex_init(&dev->mutex);

    dev->interface = interface;
    dev->udev = udev;
    usb_set_intfdata(interface, dev);

    for (i = 0; i < USB_MAXENDPOINTS; i++) {
        struct usb_host_endpoint *ep;
        ep = udev->ep_in[i];
        if (ep && (ep->desc.bmAttributes == USB_ENDPOINT_XFER_INT)) {
            dev->int_in = ep;
        }
        ep = udev->ep_out[i];
        if (ep && (ep->desc.bmAttributes == USB_ENDPOINT_XFER_INT)) {
            dev->int_out = ep;
        }
    }

    if (!dev->int_in || !dev->int_out)
        goto error;

    dev->read_buffer = kmalloc(USB_BUFFER_SIZE, GFP_KERNEL);
    dev->write_buffer = kmalloc(USB_BUFFER_SIZE, GFP_KERNEL);
    if (!dev->read_buffer || !dev->write_buffer)
        goto error;

    retval = usb_fill_int_urb(dev->int_in_urb, udev, usb_rcvintpipe(udev, dev->int_in->desc.bEndpointAddress),
                               dev->read_buffer, USB_BUFFER_SIZE, lego_usb_read_complete, dev, ep->desc.bInterval);
    if (retval < 0)
        goto error;

    usb_submit_urb(dev->int_in_urb, GFP_KERNEL);
    usb_submit_urb(dev->int_out_urb, GFP_KERNEL);

    dev_info(&udev->dev, "Lego USB Tower firmware version 1.0\n");
    return 0;

error:
    if (dev->read_buffer)
        kfree(dev->read_buffer);
    if (dev->write_buffer)
        kfree(dev->write_buffer);
    kfree(dev);
    return retval;
}
